# UserAssist - run counts (encoded)
Write-Output "`n=== UserAssist (NeuralShell runs) ==="
$uaPath = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\UserAssist'
if (Test-Path $uaPath) {
  Get-ChildItem $uaPath -Recurse -ErrorAction SilentlyContinue |
    ForEach-Object {
      $props = Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue
      $props.PSObject.Properties | Where-Object { $_.Name -match 'NeuralShell|neuralshell' -or ($_.Value -is [byte[]] -and $_.Name.Length -gt 20) } | Select-Object -First 0
    }
  # Decode common approach - search value names containing encoded paths
  Get-ChildItem "$uaPath\*\Count" -ErrorAction SilentlyContinue | ForEach-Object {
    Get-ItemProperty $_.PSPath | Get-Member -MemberType NoteProperty | Where-Object { $_.Name -notmatch '^PS' } | ForEach-Object {
      $name = $_.Name
      # ROT13 decode for UserAssist
      $decoded = -join ($name.ToCharArray() | ForEach-Object {
        $c = [int][char]$_
        if ($c -ge 65 -and $c -le 90) { [char](((($c - 65 - 13) % 26 + 26) % 26) + 65) }
        elseif ($c -ge 97 -and $c -le 122) { [char](((($c - 97 - 13) % 26 + 26) % 26) + 97) }
        else { [char]$c }
      })
      if ($decoded -match 'NeuralShell|neuralshell') {
        $val = (Get-ItemProperty $_.PSPath -Name $name).$name
        Write-Output "Decoded: $decoded"
      }
    }
  }
}

