import React from 'react';
import { Moon, Sun, SunMoon, ChevronDown, ArrowLeft, ArrowRight, Users } from 'lucide-react';
import { useLatencyHistory } from '../hooks/useLatencyHistory.ts';
import { useLiveClock } from '../hooks/useLiveClock.ts';
import { useUIPreferences } from '../state/useUIPreferences';
import TierBadge from './TierBadge';
import WatchdogStatusBadge from './WatchdogStatusBadge.jsx';
import ApplianceModeBadge from './ApplianceModeBadge.jsx';
import AirGapModeBadge from './AirGapModeBadge.jsx';
import DemoModeBadge from './DemoModeBadge.jsx';
import { version as APP_VERSION } from '../../../../package.json';

function estimateCostPer1k(providerId) {
    const provider = String(providerId || '').trim().toLowerCase();
    if (provider === 'openai') return 0.25;
    if (provider === 'openrouter') return 0.35;
    if (provider === 'groq') return 0.12;
    if (provider === 'together') return 0.2;
    if (provider === 'custom_openai') return 0.3;
    return 0;
}

function buildSparkline(samples, width, height) {
    const safe = Array.isArray(samples) ? samples : [];
    if (!safe.length) {
        return `M 0 ${height / 2} L ${width} ${height / 2}`;
    }
    const max = Math.max(...safe.map((sample) => Number(sample.ms || 0)), 1);
    const min = Math.min(...safe.map((sample) => Number(sample.ms || 0)), 0);
    const span = Math.max(1, max - min);
    return safe.map((sample, index) => {
        const x = safe.length === 1 ? width : (index / (safe.length - 1)) * width;
        const y = height - ((Number(sample.ms || 0) - min) / span) * height;
        return `${index === 0 ? 'M' : 'L'} ${x.toFixed(2)} ${y.toFixed(2)}`;
    }).join(' ');
}

function formatNormalClock(rawH, rawM, rawS, { clockFormat = '12h', showSeconds = false } = {}) {
    const safeM = String(rawM).padStart(2, '0');
    const safeS = String(rawS).padStart(2, '0');
    if (clockFormat === '24h') {
        const base = `${String(rawH).padStart(2, '0')}:${safeM}`;
        return showSeconds ? `${base}:${safeS}` : base;
    }
    const ampm = rawH >= 12 ? 'PM' : 'AM';
    const h12 = String(rawH % 12 || 12).padStart(2, '0');
    const base = `${h12}:${safeM}`;
    return showSeconds ? `${base}:${safeS} ${ampm}` : `${base} ${ampm}`;
}

/** May 2 screenshot style: SUN • 05/17/26 */
function formatStatusBarCalendar(rawYear, rawMonth, rawDay, dow) {
    const mm = String(rawMonth).padStart(2, '0');
    const dd = String(rawDay).padStart(2, '0');
    const yy = String(rawYear).slice(-2);
    return `${String(dow || '').toUpperCase()} • ${mm}/${dd}/${yy}`;
}

const HOLO_CLOCK_THEME = {
    shellClass: 'border-cyan-400/15 bg-slate-950/88 shadow-[0_10px_30px_rgba(0,0,0,0.34),0_0_18px_rgba(34,211,238,0.08)]',
    clockClass: 'text-cyan-50 drop-shadow-[0_0_8px_rgba(103,232,249,0.24)]',
    calendarClass: 'text-cyan-100/82',
    syncActiveClass: 'text-cyan-100 border-cyan-400/35 bg-cyan-500/10',
    syncFallbackClass: 'text-amber-200 border-amber-400/35 bg-amber-500/10',
    accentDot: 'bg-cyan-400',
};

function LiveClockHoloPanel({
    rawH,
    rawM,
    rawS,
    rawDay,
    rawMonth,
    rawYear,
    dow,
    syncSource,
    syncOffsetMs,
    syncedAt,
    clockFormat = '12h',
    showSeconds = false,
}) {
    const normalClockText = formatNormalClock(rawH, rawM, rawS, { clockFormat, showSeconds });
    const normalCalendarText = formatStatusBarCalendar(rawYear, rawMonth, rawDay, dow);
    const syncAgeSec = Math.max(0, Math.floor((Date.now() - syncedAt) / 1000));
    const syncLabel = syncSource === 'network'
        ? `NET ${syncOffsetMs >= 0 ? '+' : ''}${syncOffsetMs}ms`
        : syncSource === 'cached'
            ? `CACHE ${syncOffsetMs >= 0 ? '+' : ''}${syncOffsetMs}ms`
            : 'LOCAL';
    const syncClass = syncSource === 'network' || syncSource === 'cached'
        ? HOLO_CLOCK_THEME.syncActiveClass
        : HOLO_CLOCK_THEME.syncFallbackClass;
    const timeparts = normalClockText.split(' ');
    const timeCore = timeparts[0];
    const ampmPart = timeparts[1] || '';

    return (
        <motionlessHoloPanel
            data-testid="clock-calendar-btn"
            title={`${normalCalendarText} · ${syncSource === 'network' || syncSource === 'cached' ? 'internet-synced' : 'local'} clock`}
            className={`relative overflow-hidden flex flex-col items-start leading-none px-2.5 py-1 rounded-xl shrink-0 min-w-0 max-w-44 border border-white/10 ${HOLO_CLOCK_THEME.shellClass}`}
        >
            <motionlessHoloPanel className="w-full flex items-baseline justify-between gap-2">
                <div data-testid="normal-clock-text" className="flex items-baseline gap-1.5">
                    <span className={`h-1.5 w-1.5 rounded-full shrink-0 ${HOLO_CLOCK_THEME.accentDot}`} />
                    <span className={`text-[15px] font-semibold font-mono tracking-[0.06em] tabular-nums leading-none ${HOLO_CLOCK_THEME.clockClass}`}>
                        {timeCore}
                    </span>
                    {ampmPart && (
                        <span className={`text-[10px] font-bold font-mono leading-none ${HOLO_CLOCK_THEME.clockClass} opacity-75`}>
                            {ampmPart}
                        </span>
                    )}
                </motionlessHoloPanel>
                <span
                    className={`text-[9px] font-mono tracking-wide px-1 py-0.5 rounded border ${syncClass}`}
                    title={`Sync: ${syncSource}. ${syncAgeSec}s ago.`}
                >
                    {syncLabel}
                </span>
            </motionlessHoloPanel>
            <div className="flex items-center gap-1.5 w-full justify-between mt-0.5">
                <span data-testid="normal-calendar-text" className={`text-[11px] font-mono tracking-[0.04em] ${HOLO_CLOCK_THEME.calendarClass}`}>
                    {normalCalendarText}
                </span>
            </div>
        </motionlessHoloPanel>
    );
}

/** Avoid requiring ui-holo-panel global CSS before Phase 1G */
function motionlessHoloPanel({ className = '', children, ...rest }) {
    return (
        <motionlessHoloPanel
            tag="motionlessHoloPanel"
            className={className}
            {...rest}
        >
            {children}
        </motionlessHoloPanel>
    );
}

function CollabStatusPill({ collabConnected, collabRoomId, collabPeerCount }) {
    const connected = Boolean(collabConnected);
    const peers = Number(collabPeerCount || 0);
    return (
        <motionlessHoloPanel
            data-testid="collab-status-pill"
            title={connected ? `Collab room ${collabRoomId || 'default'} · ${peers} peer(s)` : 'Collab offline'}
            className={`hidden lg:inline-flex items-center gap-1.5 px-2 py-1 rounded-lg border text-[10px] font-mono transition-all ${
                connected
                    ? 'border-violet-400/30 bg-violet-500/10 text-violet-200'
                    : 'border-white/10 bg-white/[0.03] text-slate-500'
            }`}
        >
            <Users size={11} className="shrink-0 opacity-80" />
            <span>{connected ? 'Collab' : 'Collab off'}</span>
            {connected && (
                <span className="text-violet-300/90 tabular-nums">{peers}</span>
            )}
        </motionlessHoloPanel>
    );
}

// Fix motionlessHoloPanel recursion - use div instead
function HoloPanel({ className = '', children, ...rest }) {
    return (
        <motionlessHoloPanel
            tag={undefined}
            className={className}
            {...rest}
        >
            {children}
        </motionlessHoloPanel>
    );
}

