/** Recovery center shell (PrimaryWorkspaceRegion). Default false until visual/send gates pass. */
const USE_RECOVERY_CENTER_SHELL = false;

const RECOVERY_SEND_POLL_MAX_MS = 1200;
const RECOVERY_SEND_POLL_INTERVAL_MS = 50;
const OPERATOR_GUIDE_MARK = '### NeuralShell Operator Guide';

function getRecoveryMessageText(message) {
    if (!message || typeof message !== 'object') return '';
    return String(message.content ?? '');
}

function isRecoveryAssistantLikeMessage(message) {
    if (!message || typeof message !== 'object') return false;
    const role = String(message.role || '').toLowerCase();
    return role === 'kernel' || role === 'assistant';
}

function findRecoveryAssistantAfterBaseline(log, baselineLen, trimmed) {
    const tail = Array.isArray(log) ? log.slice(Math.max(0, baselineLen)) : [];
    const candidates = tail.filter(isRecoveryAssistantLikeMessage);
    if (!candidates.length) return null;

    const isHelp = /^\/help\b/i.test(String(trimmed || '').trim());
    if (isHelp) {
        return [...candidates].reverse().find((m) => {
            const text = getRecoveryMessageText(m);
            return text.includes(OPERATOR_GUIDE_MARK) || text.includes('NeuralShell Operator Guide');
        }) || null;
    }

    return candidates[candidates.length - 1];
}

async function waitForRecoveryAssistantAfterBaseline(getLog, baselineLen, trimmed) {
    const deadline = Date.now() + RECOVERY_SEND_POLL_MAX_MS;
    while (Date.now() <= deadline) {
        const found = findRecoveryAssistantAfterBaseline(getLog(), baselineLen, trimmed);
        if (found) return getRecoveryMessageText(found);
        await new Promise((resolve) => { setTimeout(resolve, RECOVERY_SEND_POLL_INTERVAL_MS); });
    }
    return '';
}

