const fs = require('fs');
const os = require('os');
const path = require('path');
const { _electron: electron } = require('playwright');

const root = path.join(__dirname, '../..');
const outDir = path.join(__dirname, 'phase-1f-collab-d-smoke');
const stamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);

const KNOWN_CONSOLE_PATTERNS = [
    /Content Security Policy/i,
    /connect-src/i,
    /violates the following/i,
    /Refused to connect/i,
    /Fetch API cannot load/i,
    /ws:\/\//i,
    /worldtimeapi/i,
    /timeapi\.io/i,
    /devtools/i,
];

function isKnownConsoleError(text) {
    const t = String(text || '');
    return KNOWN_CONSOLE_PATTERNS.some((re) => re.test(t));
}

async function dismissOverlays(page) {
    for (const testId of ['firstboot-close-btn', 'onboarding-close-btn']) {
        const btn = page.getByTestId(testId);
        if (await btn.count()) {
            await btn.first().click().catch(() => {});
            await page.waitForTimeout(250);
        }
    }
}

async function shot(page, name) {
    const p = path.join(outDir, `${name}-${stamp}.png`);
    await page.screenshot({ path: p, fullPage: false });
    return p;
}

async function sendChat(page, text) {
    const chatInput = page.getByTestId('chat-input').first();
    await chatInput.click();
    await chatInput.fill(text);
    await chatInput.press('Enter');
}

async function main() {
    fs.mkdirSync(outDir, { recursive: true });
    const userDataDir = fs.mkdtempSync(path.join(os.tmpdir(), 'neuralshell-1fcollabd-'));
    const consoleErrors = [];
    const pageErrors = [];
    const checks = {};
    const shots = {};
    let app = null;

    try {
        app = await electron.launch({
            args: ['.'],
            cwd: root,
            timeout: 120000,
            env: { ...process.env, NEURAL_USER_DATA_DIR: userDataDir, NEURAL_IGNORE_INTEGRITY: '1' },
        });
        const page = await app.firstWindow({ timeout: 180000 });
        page.on('console', (msg) => {
            if (msg.type() === 'error') consoleErrors.push(msg.text());
        });
        page.on('pageerror', (err) => pageErrors.push(String(err && err.message ? err.message : err)));

        await page.setViewportSize({ width: 1680, height: 980 });
        await page.waitForLoadState('domcontentloaded');
        await page.evaluate(() => {
            globalThis.localStorage.setItem('neuralshell_onboarding_dismissed_v1', '1');
        });
        await page.reload();
        await page.waitForLoadState('domcontentloaded');
        await page.getByTestId('top-status-bar').waitFor({ state: 'visible', timeout: 45000 });
        await dismissOverlays(page);
        await page.getByTestId('layout-control-bar').waitFor({ state: 'visible', timeout: 15000 });
        await page.getByTestId('workspace-panel').waitFor({ state: 'visible', timeout: 30000 });
        await page.getByTestId('chat-input').first().waitFor({ state: 'visible', timeout: 15000 });

        checks.recoveryCenter = await page.locator('#main-workspace').isVisible().catch(() => false)
            && (await page.getByText('Operator Hero Console', { exact: false }).first().isVisible().catch(() => false)
                || await page.getByTestId('workspace-panel').isVisible().catch(() => false));
        checks.collabPill = await page.getByTestId('collab-status-pill').isVisible().catch(() => false);
        checks.workspacePanel = await page.getByTestId('workspace-panel').isVisible().catch(() => false);

        const panel = page.getByTestId('workspace-panel').first();
        const box = await panel.boundingBox();
        checks.cursorPublishCrash = false;
        if (box) {
            for (let i = 0; i < 12; i += 1) {
                await page.mouse.move(box.x + 50 + i * 25, box.y + 100 + i * 15);
                await page.waitForTimeout(40);
            }
            checks.cursorPublishCrash = pageErrors.length > 0;
        }
        shots.afterMouseMove = await shot(page, '02-after-mousemove');

        const overlayCount = await page.locator('.pointer-events-none.fixed.inset-0.z-\\[120\\]').count().catch(() => 0);
        checks.remoteOverlayEmptyNoCrash = pageErrors.length === 0;
        checks.remoteOverlayDomWhenEmpty = overlayCount === 0;

        shots.initial = await shot(page, '01-initial');

        await sendChat(page, '/help');
        await page.waitForTimeout(1500);
        const helpText = await page.getByTestId('workspace-panel').innerText();
        checks.helpOperatorGuide = helpText.includes('### NeuralShell Operator Guide') || helpText.includes('NeuralShell Operator Guide');
        checks.helpNodeChain = helpText.includes('NodeChain prompted a vault save');
        shots.afterHelp = await shot(page, '03-after-help');

        await sendChat(page, 'test collab d recovery send');
        await page.waitForTimeout(2500);
        const freeformText = await page.getByTestId('workspace-panel').innerText();
        checks.freeformNoCrash = pageErrors.length === 0;
        checks.freeformHasUser = freeformText.toLowerCase().includes('test collab d recovery send');
        shots.afterFreeform = await shot(page, '04-after-freeform');

        await page.keyboard.press('Escape');
        await page.waitForTimeout(200);
        await page.getByTestId('command-palette-btn').click({ timeout: 8000 });
        await page.waitForTimeout(500);
        checks.commandPalette = await page.getByTestId('command-palette').isVisible().catch(() => false);
        shots.palette = await shot(page, '05-palette');
        await page.keyboard.press('Escape');
        await page.waitForTimeout(200);

        const layoutResults = {};
        for (const id of ['hud', 'compact', 'balanced', 'wide']) {
            const btn = page.getByTestId(`layout-preset-${id}-btn`);
            await btn.click({ timeout: 5000 }).catch(() => {});
            await page.waitForTimeout(400);
            layoutResults[id] = {
                workspaceVisible: await page.getByTestId('workspace-panel').isVisible().catch(() => false),
                noCrash: pageErrors.length === 0,
            };
        }
        checks.layoutPresets = layoutResults;
        shots.layoutPresets = await shot(page, '06-layout-presets');

        const unexpectedConsole = consoleErrors.filter((t) => !isKnownConsoleError(t));
        checks.pageErrors = pageErrors;
        checks.consoleErrorCount = consoleErrors.length;
        checks.unexpectedConsoleCount = unexpectedConsole.length;
        checks.realRemoteOverlayVerified = false;
        checks.realRemoteOverlayDeferred = true;

        const pass = Boolean(
            checks.recoveryCenter
            && checks.collabPill
            && checks.workspacePanel
            && !checks.cursorPublishCrash
            && checks.remoteOverlayEmptyNoCrash
            && checks.helpOperatorGuide
            && !checks.helpNodeChain
            && checks.freeformNoCrash
            && checks.freeformHasUser
            && checks.commandPalette
            && pageErrors.length === 0
            && unexpectedConsole.length === 0
            && Object.values(layoutResults).every((r) => r.workspaceVisible && r.noCrash),
        );

        const report = {
            capturedAt: new Date().toISOString(),
            flag: 'USE_RECOVERY_CENTER_SHELL=true',
            pass,
            shots,
            checks,
            consoleErrors: consoleErrors.slice(0, 40),
            unexpectedConsole: unexpectedConsole.slice(0, 20),
            pageErrors,
        };
        const reportPath = path.join(outDir, `smoke-report-${stamp}.json`);
        fs.writeFileSync(reportPath, JSON.stringify(report, null, 2));
        console.log(JSON.stringify({ pass, reportPath, shots, checks: { ...checks, layoutPresets: layoutResults } }, null, 2));
        process.exitCode = pass ? 0 : 1;
    } finally {
        if (app) await app.close().catch(() => {});
        try { fs.rmSync(userDataDir, { recursive: true, force: true }); } catch {}
    }
}

main().catch((e) => { console.error(e); process.exit(1); });

