const outDir = path.join(__dirname, 'phase-1f-collab-peer-test');
const stamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);

const KNOWN_CONSOLE_PATTERNS = [
    /Content Security Policy/i,
    /connect-src/i,
    /violates the following/i,
    /Refused to connect/i,
    /Fetch API cannot load/i,
    /ws:\/\//i,
    /worldtimeapi/i,
    /timeapi\.io/i,
    /devtools/i,
];

function isKnownConsoleError(text) {
    return KNOWN_CONSOLE_PATTERNS.some((re) => re.test(String(text || '')));
}

async function dismissOverlays(page) {
    for (const testId of ['firstboot-close-btn', 'onboarding-close-btn']) {
        const btn = page.getByTestId(testId);
        if (await btn.count()) {
            await btn.first().click().catch(() => {});
            await page.waitForTimeout(250);
        }
    }
}

async function shot(page, name) {
    const p = path.join(outDir, `${name}-${stamp}.png`);
    await page.screenshot({ path: p, fullPage: false });
    return p;
}

async function sendChat(page, text) {
    const chatInput = page.getByTestId('chat-input').first();
    await chatInput.click();
    await chatInput.fill(text);
    await chatInput.press('Enter');
}

async function readCollabProbe(page) {
    return page.evaluate(async () => {
        const pill = document.querySelector('[data-testid="collab-status-pill"]');
        let status = null;
        try {
            status = await window.api.collab.getStatus();
        } catch (err) {
            status = { error: String(err && err.message ? err.message : err) };
        }
        const overlayDots = document.querySelectorAll(
            '.pointer-events-none.fixed.inset-0.z-\\[120\\] .rounded-full.bg-emerald-300',
        );
        return {
            status,
            pillTitle: pill ? pill.getAttribute('title') || '' : '',
            pillText: pill ? (pill.textContent || '').trim() : '',
            remoteCursorDotCount: overlayDots.length,
        };
    });
}

async function waitForCollabConnected(page, label, timeoutMs = 45000) {
    const start = Date.now();
    while (Date.now() - start < timeoutMs) {
        const probe = await readCollabProbe(page);
        if (probe.status && probe.status.running && probe.pillText && !/collab off/i.test(probe.pillText)) {
            return probe;
        }
        await page.waitForTimeout(400);
    }
    throw new Error(`Collab did not connect on ${label} within ${timeoutMs}ms`);
}

async function moveMouseOverWorkspace(page) {
    const panel = page.getByTestId('workspace-panel').first();
    const box = await panel.boundingBox();
    if (!box) return false;
    for (let i = 0; i < 14; i += 1) {
        await page.mouse.move(box.x + 60 + i * 28, box.y + 120 + i * 18);
        await page.waitForTimeout(60);
    }
    return true;
}

async function openSecondWindow(electronApp) {
    await electronApp.evaluate(({ appRoot }) => {
        const { BrowserWindow } = require('electron');
        const path = require('path');
        const win = new BrowserWindow({
            width: 1280,
            height: 900,
            x: 80,
            y: 40,
            webPreferences: {
                preload: path.join(appRoot, 'src', 'preload.js'),
                contextIsolation: true,
                nodeIntegration: false,
                sandbox: true,
                enableRemoteModule: false,
                webSecurity: true,
            },
        });
        win.loadFile(path.join(appRoot, 'dist-renderer', 'index.html'));
    }, { appRoot: root });
    await new Promise((r) => setTimeout(r, 1500));
}

async function main() {
    fs.mkdirSync(outDir, { recursive: true });
    const userDataDir = fs.mkdtempSync(path.join(os.tmpdir(), 'neuralshell-collab-peer-'));
    const consoleA = [];
    const consoleB = [];
    const pageErrorsA = [];
    const pageErrorsB = [];
    const shots = {};
    let app = null;
    let pageA = null;
    let pageB = null;

    try {
        app = await electron.launch({
            args: ['.'],
            cwd: root,
            timeout: 120000,
            env: {
                ...process.env,
                NEURAL_USER_DATA_DIR: userDataDir,
                NEURAL_IGNORE_INTEGRITY: '1',
                NEURAL_COLLAB_TEST_CSP: '1',
            },
        });

        pageA = await app.firstWindow({ timeout: 180000 });
        pageA.on('console', (msg) => {
            if (msg.type() === 'error') consoleA.push(msg.text());
        });
        pageA.on('pageerror', (err) => pageErrorsA.push(String(err && err.message ? err.message : err)));

        await pageA.setViewportSize({ width: 1280, height: 900 });
        await pageA.waitForLoadState('domcontentloaded');
        await pageA.evaluate(() => {
            globalThis.localStorage.setItem('neuralshell_onboarding_dismissed_v1', '1');
        });
        await pageA.reload();
        await pageA.waitForLoadState('domcontentloaded');
        await pageA.getByTestId('top-status-bar').waitFor({ state: 'visible', timeout: 45000 });
        await dismissOverlays(pageA);
        await pageA.getByTestId('workspace-panel').waitFor({ state: 'visible', timeout: 30000 });

        await openSecondWindow(app);
        const windows = app.windows();
        pageB = windows.length > 1 ? windows[1] : windows[0];
        if (pageB === pageA) {
            throw new Error('Second BrowserWindow did not open');
        }

        pageB.on('console', (msg) => {
            if (msg.type() === 'error') consoleB.push(msg.text());
        });
        pageB.on('pageerror', (err) => pageErrorsB.push(String(err && err.message ? err.message : err)));

        await pageB.setViewportSize({ width: 1280, height: 900 });
        await pageB.waitForLoadState('domcontentloaded');
        await pageB.evaluate(() => {
            globalThis.localStorage.setItem('neuralshell_onboarding_dismissed_v1', '1');
        });
        await pageB.reload();
        await pageB.waitForLoadState('domcontentloaded');
        await pageB.getByTestId('top-status-bar').waitFor({ state: 'visible', timeout: 45000 });
        await dismissOverlays(pageB);
        await pageB.getByTestId('workspace-panel').waitFor({ state: 'visible', timeout: 30000 });

        shots.initial = await shot(pageA, '00-dual-windows-initial');

        const probeA0 = await waitForCollabConnected(pageA, 'window A');
        const probeB0 = await waitForCollabConnected(pageB, 'window B');

        const roomA = String(probeA0.status?.roomId || probeA0.pillTitle.match(/room ([^·]+)/)?.[1]?.trim() || '');
        const roomB = String(probeB0.status?.roomId || probeB0.pillTitle.match(/room ([^·]+)/)?.[1]?.trim() || '');
        const roomFromPillA = probeA0.pillTitle;
        const roomFromPillB = probeB0.pillTitle;

        const collabPort = Number(probeA0.status?.port || probeB0.status?.port || 0);

        await pageA.bringToFront();
        await moveMouseOverWorkspace(pageA);
        await pageA.waitForTimeout(800);
        const probeBAfterA = await readCollabProbe(pageB);
        shots.windowBShowsRemoteFromA = await shot(pageB, '02-window-b-shows-remote-cursor-from-a');

        await pageB.bringToFront();
        await moveMouseOverWorkspace(pageB);
        await pageB.waitForTimeout(800);
        const probeAAfterB = await readCollabProbe(pageA);
        shots.windowAShowsRemoteFromB = await shot(pageA, '01-window-a-shows-remote-cursor-from-b');

        const peerCountA = Number((probeAAfterB.pillText.match(/(\d+)\s*$/) || [])[1] || 0);
        const peerCountB = Number((probeBAfterA.pillText.match(/(\d+)\s*$/) || [])[1] || 0);

        const remoteCursorAtoB = probeBAfterA.remoteCursorDotCount > 0;
        const remoteCursorBtoA = probeAAfterB.remoteCursorDotCount > 0;

        shots.collabPill = await shot(pageA, '03-collab-pill-peer-count');

        await pageA.bringToFront();
        await sendChat(pageA, '/help');
        await pageA.waitForTimeout(1500);
        const helpText = await pageA.getByTestId('workspace-panel').innerText();
        const helpOperatorGuide = helpText.includes('### NeuralShell Operator Guide')
            || helpText.includes('NeuralShell Operator Guide');
        const helpNodeChain = helpText.includes('NodeChain prompted a vault save');

        await sendChat(pageA, 'test collab peer recovery send');
        await pageA.waitForTimeout(2500);
        const freeformText = await pageA.getByTestId('workspace-panel').innerText();
        const freeformNoCrash = pageErrorsA.length === 0 && pageErrorsB.length === 0;
        const freeformHasUser = freeformText.toLowerCase().includes('test collab peer recovery send');

        const sameRoom = roomFromPillA && roomFromPillB
            && roomFromPillA === roomFromPillB;

        const unexpectedConsole = [...consoleA, ...consoleB].filter((t) => !isKnownConsoleError(t));

        const report = {
            capturedAt: new Date().toISOString(),
            flag: 'USE_RECOVERY_CENTER_SHELL=true',
            cspTestEnv: 'NEURAL_COLLAB_TEST_CSP=1',
            collabServer: {
                port: collabPort,
                running: Boolean(probeA0.status?.running),
                host: probeA0.status?.host || '127.0.0.1',
                requestedPort: probeA0.status?.requestedPort,
            },
            windowA: {
                roomPillTitle: roomFromPillA,
                probe: probeAAfterB,
                peerCount: peerCountA,
            },
            windowB: {
                roomPillTitle: roomFromPillB,
                probe: probeBAfterA,
                peerCount: peerCountB,
            },
            sameRoom,
            peerCountIncremented: peerCountA >= 1 && peerCountB >= 1,
            remoteCursorAtoB,
            remoteCursorBtoA,
            helpOperatorGuide,
            helpNodeChain,
            freeformNoCrash,
            freeformHasUser,
            pageErrorsA,
            pageErrorsB,
            consoleErrorsA: consoleA,
            consoleErrorsB: consoleB,
            unexpectedConsole,
            shots,
            pass: Boolean(
                probeA0.status?.running
                && probeB0.status?.running
                && sameRoom
                && remoteCursorAtoB
                && remoteCursorBtoA
                && peerCountA >= 1
                && peerCountB >= 1
                && helpOperatorGuide
                && !helpNodeChain
                && freeformNoCrash
                && freeformHasUser
                && pageErrorsA.length === 0
                && pageErrorsB.length === 0
                && unexpectedConsole.length === 0,
            ),
        };

        const reportPath = path.join(outDir, `peer-test-report-${stamp}.json`);
        fs.writeFileSync(reportPath, JSON.stringify(report, null, 2));
        fs.writeFileSync(path.join(outDir, `console-window-a-${stamp}.txt`), consoleA.join('\n'));
        fs.writeFileSync(path.join(outDir, `console-window-b-${stamp}.txt`), consoleB.join('\n'));
        fs.writeFileSync(path.join(outDir, `git-status-${stamp}.txt`), '');

        console.log(JSON.stringify({ pass: report.pass, reportPath, collabPort, report }, null, 2));
        process.exitCode = report.pass ? 0 : 1;
    } finally {
        if (app) await app.close().catch(() => {});
        try { fs.rmSync(userDataDir, { recursive: true, force: true }); } catch {}
    }
}

main().catch((err) => {
    console.error(err);
    process.exit(1);
});

