const fs = require('fs');
const os = require('os');
const path = require('path');
const WebSocket = require('ws');
const { _electron: electron } = require('playwright');

const root = path.join(__dirname, '../..');
const outDir = path.join(__dirname, 'phase-1f-collab-peer-diagnostic');
const stamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
const serverLogPath = path.join(outDir, 'server-handshake.log');

const KNOWN_CONSOLE = [/Content Security Policy/i, /worldtimeapi/i, /timeapi\.io/i, /devtools/i];

async function probeRendererWs(page, host, port) {
    return page.evaluate(({ host, port }) => new Promise((resolve) => {
        const url = `ws://${host}:${port}`;
        const timeline = [];
        const log = (step, extra) => timeline.push({ step, ...extra, t: Date.now() });
        log('start', { url });
        let ws;
        try {
            ws = new WebSocket(url);
        } catch (err) {
            resolve({ url, ok: false, threw: String(err && err.message ? err.message : err), timeline });
            return;
        }
        ws.onopen = () => {
            log('open', { readyState: ws.readyState });
            resolve({ url, ok: true, timeline, readyState: ws.readyState });
            try { ws.close(); } catch {}
        };
        ws.onerror = () => {
            log('error', { readyState: ws.readyState });
        };
        ws.onclose = (event) => {
            log('close', {
                code: event.code,
                reason: event.reason,
                wasClean: event.wasClean,
                readyState: ws.readyState,
            });
            if (!timeline.some((e) => e.step === 'open')) {
                resolve({
                    url,
                    ok: false,
                    timeline,
                    closeCode: event.code,
                    closeReason: event.reason,
                    wasClean: event.wasClean,
                });
            }
        };
        setTimeout(() => {
            log('timeout', { readyState: ws.readyState });
            resolve({ url, ok: false, timeout: true, timeline, readyState: ws.readyState });
            try { ws.close(); } catch {}
        }, 6000);
    }), { host, port });
}

async function probeCsp(page) {
    return page.evaluate(async () => {
        const metas = Array.from(document.querySelectorAll('meta[http-equiv="Content-Security-Policy"]'))
            .map((m) => m.getAttribute('content') || '');
        let headerCsp = null;
        try {
            const res = await fetch(document.location.href);
            headerCsp = res.headers.get('content-security-policy');
        } catch (err) {
            headerCsp = `fetch-failed:${err && err.message ? err.message : err}`;
        }
        return {
            href: document.location.href,
            origin: document.location.origin || 'null',
            protocol: document.location.protocol,
            metaCsp: metas,
            headerCsp,
            hasConnectSrcNone: [...metas, headerCsp].filter(Boolean).some((v) => /connect-src[^;]*'none'/i.test(v)),
        };
    });
}

function probeNodeWs(host, port, headers = {}) {
    return new Promise((resolve) => {
        const url = `ws://${host}:${port}`;
        const timeline = [];
        const ws = new WebSocket(url, { headers });
        ws.on('open', () => {
            timeline.push({ step: 'open', t: Date.now() });
            ws.send(JSON.stringify({ action: 'join', room: 'diag', peerId: 'node-diag' }));
        });
        ws.on('message', (raw) => {
            timeline.push({ step: 'message', data: String(raw).slice(0, 200), t: Date.now() });
            ws.close();
            resolve({ url, ok: true, timeline, headers });
        });
        ws.on('error', (err) => {
            timeline.push({ step: 'error', message: err.message, t: Date.now() });
            resolve({ url, ok: false, timeline, headers, error: err.message });
        });
        ws.on('close', (code, reason) => {
            timeline.push({ step: 'close', code, reason: String(reason || ''), t: Date.now() });
        });
        setTimeout(() => resolve({ url, ok: false, timeout: true, timeline, headers }), 6000);
    });
}

function readServerLog() {
    if (!fs.existsSync(serverLogPath)) return [];
    return fs.readFileSync(serverLogPath, 'utf8').trim().split('\n').filter(Boolean).map((line) => {
        try { return JSON.parse(line); } catch { return { raw: line }; }
    });
}

async function main() {
    fs.mkdirSync(outDir, { recursive: true });
    if (fs.existsSync(serverLogPath)) fs.unlinkSync(serverLogPath);

    const userDataDir = fs.mkdtempSync(path.join(os.tmpdir(), 'neuralshell-collab-diag-'));
    const securityBlocks = [];
    const consoleErrors = [];
    let app = null;

    const report = {
        capturedAt: new Date().toISOString(),
        env: {
            NEURAL_COLLAB_TEST_CSP: '1',
            NEURAL_COLLAB_WS_DIAG: '1',
            NEURAL_IGNORE_INTEGRITY: '1',
        },
    };

    try {
        app = await electron.launch({
            args: ['.'],
            cwd: root,
            timeout: 180000,
            env: {
                ...process.env,
                NEURAL_USER_DATA_DIR: userDataDir,
                NEURAL_IGNORE_INTEGRITY: '1',
                NEURAL_COLLAB_TEST_CSP: '1',
                NEURAL_COLLAB_WS_DIAG: '1',
                NEURAL_COLLAB_WS_DIAG_LOG: serverLogPath,
            },
        });

        const page = await app.firstWindow({ timeout: 180000 });
        page.on('console', (msg) => {
            const text = msg.text();
            if (/\[SECURITY\] Blocked renderer network request/i.test(text)) {
                securityBlocks.push(text);
            }
            if (msg.type() === 'error') consoleErrors.push(text);
        });

        await page.waitForLoadState('domcontentloaded');
        report.csp = await probeCsp(page);

        const status = await page.evaluate(() => window.api.collab.getStatus());
        const host = String(status.host || '127.0.0.1');
        const port = Number(status.port || 0);
        const requestedPort = Number(status.requestedPort || 55116);
        report.collabStatus = status;
        report.rendererUrl = {
            fromHook: `ws://${host}:${port}`,
            usesActualBoundPort: port > 0 && port !== requestedPort ? true : port === requestedPort,
            requestedPort,
            boundPort: port,
        };

        const hosts = ['127.0.0.1', 'localhost'];
        report.rendererWsVariants = {};
        for (const h of hosts) {
            report.rendererWsVariants[h] = await probeRendererWs(page, h, port);
        }

        report.nodeWs = {
            plain: await probeNodeWs(host, port),
            originNull: await probeNodeWs(host, port, { Origin: 'null' }),
            originFile: await probeNodeWs(host, port, { Origin: 'file://' }),
        };

        await page.waitForTimeout(1500);
        report.securityBlocks = securityBlocks;
        report.consoleErrorsFiltered = consoleErrors.filter((t) => !KNOWN_CONSOLE.some((re) => re.test(t)));
        report.serverHandshakeLog = readServerLog();

        const rendererAnyOpen = Object.values(report.rendererWsVariants).some((v) => v.ok);
        const nodeOpen = report.nodeWs.plain.ok;
        const serverSawRendererUpgrade = report.serverHandshakeLog.some((e) =>
            e.event === 'http_upgrade' && e.origin && String(e.origin).includes('file'));
        const serverSawAnyUpgrade = report.serverHandshakeLog.some((e) => e.event === 'http_upgrade');
        const blockedWsInConsole = securityBlocks.some((t) => /^ws:\/\//i.test(t) || t.includes('ws://'));

        let rootCause = 'F';
        let rootCauseLabel = 'other';
        if (report.csp.hasConnectSrcNone || (report.csp.headerCsp && /connect-src[^;]*'none'/i.test(report.csp.headerCsp))) {
            rootCause = 'A';
            rootCauseLabel = 'CSP still active';
        } else if (port <= 0 || report.rendererUrl.usesActualBoundPort === false && port === 55116 && status.running) {
            rootCause = 'B';
            rootCauseLabel = 'Renderer using wrong port';
        } else if (blockedWsInConsole) {
            rootCause = 'F';
            rootCauseLabel = 'Zero-Renderer Network Lockdown (onBeforeRequest) blocks ws:// from renderer';
        } else if (serverSawRendererUpgrade && !rendererAnyOpen) {
            rootCause = 'C';
            rootCauseLabel = 'Origin/header rejection';
        } else if (!serverSawAnyUpgrade && !rendererAnyOpen && nodeOpen) {
            rootCause = 'F';
            rootCauseLabel = 'Renderer request blocked before server (likely Electron webRequest lockdown)';
        } else if (!rendererAnyOpen && nodeOpen) {
            rootCause = 'E';
            rootCauseLabel = 'Electron/file:// WebSocket limitation or pre-connect block';
        }

        report.classification = { code: rootCause, label: rootCauseLabel };
        report.summary = {
            rendererAnyOpen,
            nodeOpen,
            serverSawAnyUpgrade,
            serverSawRendererUpgrade,
            blockedWsInConsole,
        };

        report.recommendedFix = blockedWsInConsole || (!serverSawAnyUpgrade && !rendererAnyOpen && nodeOpen)
            ? "Allow ws://127.0.0.1 and ws://localhost on dynamic collab port in session.defaultSession.webRequest.onBeforeRequest (read bound port from ensureCollabSignalServer().status()). Env-gate with NEURAL_COLLAB_TEST_CSP or always for loopback collab. Not CSP — network lockdown at main.js ~L1756–1774."
            : rootCause === 'A'
                ? 'Relax connect-src for actual bound collab port when collab enabled.'
                : 'Further investigation required.';

