const fs = require('fs');
const os = require('os');
const path = require('path');
const { _electron: electron } = require('playwright');

const root = path.join(__dirname, '../..');
const outDir = path.join(__dirname, 'phase-1f-collab-peer-cursor-diag');
const stamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
const serverLogPath = path.join(outDir, 'server-cursor.log');

function collectDiagLogs(store, msg) {
    const text = msg.text();
    if (text.includes('[COLLAB-CURSOR-DIAG]')) {
        store.push({ type: msg.type(), text });
    }
}

async function dismissOverlays(page) {
    for (const testId of ['firstboot-close-btn', 'onboarding-close-btn']) {
        const btn = page.getByTestId(testId);
        if (await btn.count()) {
            await btn.first().click().catch(() => {});
            await page.waitForTimeout(250);
        }
    }
}

async function readCollabProbe(page) {
    return page.evaluate(async () => {
        const pill = document.querySelector('[data-testid="collab-status-pill"]');
        let status = null;
        try {
            status = await window.api.collab.getStatus();
        } catch (err) {
            status = { error: String(err && err.message ? err.message : err) };
        }
        const diag = globalThis.__nsCollabDiag || null;
        const overlayDots = document.querySelectorAll(
            '.pointer-events-none.fixed.inset-0.z-\\[120\\] .rounded-full.bg-emerald-300',
        );
        return {
            status,
            pillTitle: pill ? pill.getAttribute('title') || '' : '',
            pillText: pill ? (pill.textContent || '').trim() : '',
            remoteCursorDotCount: overlayDots.length,
            diag: diag
                ? {
                    connected: Boolean(diag.connected),
                    peerId: String(diag.peerId || ''),
                    roomId: String(diag.roomId || ''),
                    socketReadyState: Number(diag.socketReadyState()),
                    remoteCursorPeerIds: diag.remoteCursorPeerIds(),
                    remoteCursors: diag.remoteCursors(),
                }
                : null,
        };
    });
}

async function waitForCollabConnected(page, label, timeoutMs = 90000) {
    const start = Date.now();
    while (Date.now() - start < timeoutMs) {
        const probe = await readCollabProbe(page);
        const serverUp = probe.status && probe.status.running && !probe.status.error;
        const pillOn = probe.pillText && !/collab off/i.test(probe.pillText);
        const diagReady = probe.diag && probe.diag.connected && probe.diag.socketReadyState === 1;
        if (serverUp && pillOn && diagReady) return probe;
        await page.waitForTimeout(400);
    }
    const last = await readCollabProbe(page);
    throw new Error(`Collab did not connect on ${label} within ${timeoutMs}ms; last=${JSON.stringify(last)}`);
}

async function moveMouseOverWorkspace(page, label) {
    const panel = page.getByTestId('workspace-panel').first();
    await panel.waitFor({ state: 'visible', timeout: 30000 });
    const box = await panel.boundingBox();
    if (!box) {
        return { moved: false, reason: 'no-bounding-box', label };
    }
    const coords = [];
    for (let i = 0; i < 16; i += 1) {
        const x = Math.round(box.x + 48 + i * 24);
        const y = Math.round(box.y + 96 + i * 16);
        coords.push({ x, y });
        await page.mouse.move(x, y);
        await page.waitForTimeout(100);
    }
    return { moved: true, label, coords, box };
}

async function dispatchMouseMovesOnPanel(page, label) {
    return page.evaluate((tag) => {
        const el = document.querySelector('[data-testid="workspace-panel"]');
        if (!el) return { ok: false, reason: 'no-panel', tag };
        const rect = el.getBoundingClientRect();
        let dispatched = 0;
        for (let i = 0; i < 14; i += 1) {
            const clientX = Math.round(rect.left + 80 + i * 28);
            const clientY = Math.round(rect.top + 120 + i * 18);
            el.dispatchEvent(new MouseEvent('mousemove', {
                bubbles: true,
                cancelable: true,
                clientX,
                clientY,
                view: window,
            }));
            dispatched += 1;
        }
        return {
            ok: true,
            tag,
            dispatched,
            rect: { left: rect.left, top: rect.top, width: rect.width, height: rect.height },
        };
    }, label);
}

async function forcePublishCursor(page, x, y) {
    return page.evaluate(({ px, py }) => {
        const diag = globalThis.__nsCollabDiag;
        if (!diag || typeof diag.publish !== 'function') {
            return { ok: false, reason: 'no-diag-publish' };
        }
        const ok = diag.publish('cursor', { x: px, y: py });
        return {
            ok: Boolean(ok),
            peerId: String(diag.peerId || ''),
            roomId: String(diag.roomId || ''),
            socketReadyState: Number(diag.socketReadyState()),
            remoteAfter: diag.remoteCursorPeerIds(),
        };
    }, { px: x, py: y });
}

async function openSecondWindow(electronApp) {
    const preloadPath = path.join(root, 'src', 'preload.js');
    const indexPath = path.join(root, 'dist-renderer', 'index.html');
    const windowPromise = electronApp.waitForEvent('window', { timeout: 90000 });
    await electronApp.evaluate(({ BrowserWindow }, opts) => {
        const win = new BrowserWindow({
            width: 1280,
            height: 900,
            x: 80,
            y: 40,
            show: true,
            webPreferences: {
                preload: opts.preloadPath,
                contextIsolation: true,
                nodeIntegration: false,
                sandbox: false,
                enableRemoteModule: false,
                webSecurity: opts.webSecurity !== false,
            },
        });
        win.loadFile(opts.indexPath);
    }, { preloadPath, indexPath, webSecurity: false });
    return windowPromise;
}

function parseServerLog() {
    if (!fs.existsSync(serverLogPath)) return [];
    return fs.readFileSync(serverLogPath, 'utf8')
        .split('\n')
        .filter(Boolean)
        .map((line) => {
            try {
                return JSON.parse(line);
            } catch {
                return { raw: line };
            }
        });
}

async function runPhase({ app, pageA, pageB, phaseName, logsA, logsB }) {
    const probeA0 = await waitForCollabConnected(pageA, `${phaseName} window A`);
    const probeB0 = await waitForCollabConnected(pageB, `${phaseName} window B`);

    const moveA = await moveMouseOverWorkspace(pageA, `${phaseName}-playwright-move-A`);
    await pageA.waitForTimeout(600);
    const dispatchA = await dispatchMouseMovesOnPanel(pageA, `${phaseName}-dispatch-A`);
    await pageA.waitForTimeout(600);
    const forceA = await forcePublishCursor(pageA, 640, 360);
    await pageA.waitForTimeout(800);

    const probeBAfterA = await readCollabProbe(pageB);

    await pageB.bringToFront();
    const moveB = await moveMouseOverWorkspace(pageB, `${phaseName}-playwright-move-B`);
    await pageB.waitForTimeout(600);
    const dispatchB = await dispatchMouseMovesOnPanel(pageB, `${phaseName}-dispatch-B`);
    await pageB.waitForTimeout(600);
    const forceB = await forcePublishCursor(pageB, 720, 420);
    await pageB.waitForTimeout(800);

    const probeAAfterB = await readCollabProbe(pageA);

    await pageA.screenshot({ path: path.join(outDir, `${phaseName}-window-a-${stamp}.png`) });
    await pageB.screenshot({ path: path.join(outDir, `${phaseName}-window-b-${stamp}.png`) });

    const diagA = logsA.filter((e) => e.text.includes('mw-publish') || e.text.includes('publish-cursor'));
    const diagB = logsB.filter((e) => e.text.includes('ws-cursor-in'));

    return {
        phaseName,
        probeA0,
        probeB0,
        moveA,
        dispatchA,
        forceA,
        probeBAfterA,
        moveB,
        dispatchB,
        forceB,
        probeAAfterB,
        rendererLogs: {
            windowA_publishRelated: diagA.slice(-20),
            windowB_cursorInRelated: diagB.slice(-20),
            windowA_allDiagCount: logsA.length,
            windowB_allDiagCount: logsB.length,
        },
    };
}

async function main() {
    fs.mkdirSync(outDir, { recursive: true });
    if (fs.existsSync(serverLogPath)) fs.unlinkSync(serverLogPath);

    const userDataDir = fs.mkdtempSync(path.join(os.tmpdir(), 'neuralshell-collab-cursor-diag-'));
    const logsA = [];
    const logsB = [];
    let app = null;
    let pageA = null;
    let pageB = null;

    try {
        app = await electron.launch({
            args: ['.'],
            cwd: root,
            timeout: 120000,
            env: {
                ...process.env,
                NEURAL_USER_DATA_DIR: userDataDir,
                NEURAL_IGNORE_INTEGRITY: '1',
                NEURAL_COLLAB_TEST_CSP: '1',
                NEURAL_COLLAB_CURSOR_DIAG: '1',
                NEURAL_COLLAB_CURSOR_DIAG_LOG: serverLogPath,
            },
        });

        pageA = await app.firstWindow({ timeout: 180000 });
        pageA.on('console', (msg) => collectDiagLogs(logsA, msg));
        pageB = null;

        await pageA.setViewportSize({ width: 1280, height: 900 });
        await pageA.waitForLoadState('domcontentloaded');
        await pageA.evaluate(() => {
            globalThis.localStorage.setItem('neuralshell_onboarding_dismissed_v1', '1');
        });
        await pageA.reload({ waitUntil: 'domcontentloaded', timeout: 120000 });
        await pageA.getByTestId('top-status-bar').waitFor({ state: 'visible', timeout: 60000 });
        await dismissOverlays(pageA);
        await pageA.getByTestId('workspace-panel').waitFor({ state: 'visible', timeout: 30000 });

        pageB = await openSecondWindow(app);
        pageB.on('console', (msg) => collectDiagLogs(logsB, msg));
        await pageB.setViewportSize({ width: 1280, height: 900 });
        await pageB.evaluate(() => {
            globalThis.localStorage.setItem('neuralshell_onboarding_dismissed_v1', '1');
        });
        await pageB.getByTestId('top-status-bar').waitFor({ state: 'visible', timeout: 120000 });
        await dismissOverlays(pageB);
        await pageB.getByTestId('workspace-panel').waitFor({ state: 'visible', timeout: 30000 });

        const recoveryPhase = await runPhase({
            app,
            pageA,
            pageB,
            phaseName: 'recovery-multiworkspace',
            logsA,
            logsB,
        });

        const serverLog = parseServerLog();
        const joins = serverLog.filter((e) => e.event === 'join');
        const publishes = serverLog.filter((e) => e.event === 'publish-cursor');
        const drops = serverLog.filter((e) => e.event === 'publish-drop');

        const classify = () => {
            const mwPublishLogs = logsA.filter((e) => e.text.includes('mw-publish'));
            const publishCursorLogs = logsA.filter((e) => e.text.includes('publish-cursor'));
            const publishSkipLogs = logsA.filter((e) => e.text.includes('publish-skip'));
            const cursorInB = logsB.filter((e) => e.text.includes('ws-cursor-in'));
            const forceOk = Boolean(recoveryPhase.forceA && recoveryPhase.forceA.ok);
            const remoteB = (recoveryPhase.probeBAfterA.diag && recoveryPhase.probeBAfterA.diag.remoteCursorPeerIds) || [];
            const dotsB = recoveryPhase.probeBAfterA.remoteCursorDotCount;

            if (mwPublishLogs.length === 0 && publishCursorLogs.length === 0 && !forceOk) {
                if (publishSkipLogs.length > 0) return { code: 'B', label: 'publish not called / socket not open' };
                return { code: 'A', label: 'MultiWorkspace mousemove/publish path not firing' };
            }
            if (forceOk && publishes.length === 0) return { code: 'D', label: 'server did not receive cursor publish' };
            if (publishes.length > 0 && publishes.every((p) => p.broadcastCount === 0)) {
                return { code: 'D', label: 'server received but did not broadcast (room peer count 0)' };
            }
            if (publishes.some((p) => p.broadcastCount > 0) && cursorInB.length === 0) {
                return { code: 'E', label: 'peer renderer did not apply remoteCursors' };
            }
            if (cursorInB.length > 0 && remoteB.length === 0) {
                return { code: 'E', label: 'cursor-in logged but remoteCursors empty' };
            }
            if (remoteB.length > 0 && dotsB === 0) return { code: 'F', label: 'remoteCursors set but overlay DOM missing' };
            if (remoteB.length > 0 && dotsB > 0) return { code: 'PASS', label: 'cursor pipeline works in diag run' };
            if (forceOk && remoteB.length === 0) return { code: 'E', label: 'forced publish did not reach observer remoteCursors' };
            return { code: 'H', label: 'harness/timing inconclusive — inspect logs' };
        };

        const rootCause = classify();

        const report = {
            capturedAt: new Date().toISOString(),
            slice: '1F-C-COLLAB-PEER-CURSOR-DIAG',
            flag: 'USE_RECOVERY_CENTER_SHELL=true',
            env: {
                NEURAL_COLLAB_TEST_CSP: '1',
                NEURAL_COLLAB_CURSOR_DIAG: '1',
            },
            collabServer: recoveryPhase.probeA0.status,
            recoveryPhase,
            serverLogSummary: {
                joinEvents: joins,
                publishCursorEvents: publishes,
                publishDropEvents: drops,
                totalLines: serverLog.length,
            },
            rootCause,
            smallestRecommendedFix: rootCause.code === 'D' && publishes.some((p) => p.roomSize < 2)
                ? 'Ensure both renderer clients complete join before publish; verify second window shares same Electron collab server and room membership (roomSize >= 2 on publish).'
                : rootCause.code === 'A' || rootCause.code === 'B'
                    ? 'Wire collab mousemove on the element that receives real pointer events, or call publish from a bubbling capture listener; verify collab prop reaches MultiWorkspace when flag true.'
                    : rootCause.code === 'E'
                        ? 'Fix useCollabRoom inbound handler or eventType/payload parsing if server broadcasts but remoteCursors stays empty.'
                        : rootCause.code === 'F'
                            ? 'Render remote cursor overlay unconditionally (match WorkspacePanel) when remoteCursors has keys.'
                            : 'See PEER-CURSOR-DIAG-REPORT.md evidence section.',
        };

        fs.writeFileSync(path.join(outDir, `cursor-diag-report-${stamp}.json`), JSON.stringify(report, null, 2));
        fs.writeFileSync(path.join(outDir, `renderer-logs-a-${stamp}.json`), JSON.stringify(logsA, null, 2));
        fs.writeFileSync(path.join(outDir, `renderer-logs-b-${stamp}.json`), JSON.stringify(logsB, null, 2));
        fs.copyFileSync(serverLogPath, path.join(outDir, `server-cursor-copy-${stamp}.log`));

        console.log(JSON.stringify({
            reportPath: path.join(outDir, `cursor-diag-report-${stamp}.json`),
            rootCause,
            publishCount: publishes.length,
            broadcastMax: publishes.reduce((m, p) => Math.max(m, p.broadcastCount || 0), 0),
            remoteB: recoveryPhase.probeBAfterA.diag?.remoteCursorPeerIds,
        }, null, 2));
    } finally {
        if (app) await app.close().catch(() => {});
        try { fs.rmSync(userDataDir, { recursive: true, force: true }); } catch {}
    }
}

main().catch((err) => {
    console.error(err);
    process.exit(1);
});

