const fs = require('fs');
const os = require('os');
const path = require('path');
const { _electron: electron } = require('playwright');

const root = path.join(__dirname, '../..');
const outDir = path.join(__dirname, 'phase-1f-collab-peer-proof');
const stamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);

async function dismissOverlays(page) {
    for (const testId of ['firstboot-close-btn', 'onboarding-close-btn']) {
        const btn = page.getByTestId(testId);
        if (await btn.count()) await btn.first().click().catch(() => {});
    }
}

async function readCollabProbe(page) {
    return page.evaluate(async () => {
        const pill = document.querySelector('[data-testid="collab-status-pill"]');
        let status = null;
        try { status = await window.api.collab.getStatus(); } catch (e) { status = { error: String(e.message || e) }; }
        const dots = document.querySelectorAll('.pointer-events-none.fixed.inset-0.z-\\[120\\] .rounded-full.bg-emerald-300');
        return {
            status,
            pillTitle: pill?.getAttribute('title') || '',
            pillText: (pill?.textContent || '').trim(),
            remoteCursorDotCount: dots.length,
        };
    });
}

async function waitCollab(page) {
    for (let i = 0; i < 180; i += 1) {
        const p = await readCollabProbe(page);
        if (p.status?.running && p.pillText && !/collab off/i.test(p.pillText)) return p;
        await page.waitForTimeout(500);
    }
    throw new Error('collab timeout');
}

async function move(page) {
    const box = await page.getByTestId('workspace-panel').first().boundingBox();
    if (!box) return;
    for (let i = 0; i < 12; i += 1) {
        await page.mouse.move(box.x + 80 + i * 24, box.y + 100 + i * 16);
        await page.waitForTimeout(80);
    }
    await page.evaluate(() => {
        const el = document.querySelector('[data-testid="workspace-panel"]');
        if (!el) return;
        const r = el.getBoundingClientRect();
        for (let i = 0; i < 10; i += 1) {
            el.dispatchEvent(new MouseEvent('mousemove', { bubbles: true, clientX: r.left + 100 + i * 20, clientY: r.top + 120 + i * 14 }));
        }
    });
}

async function waitDots(page) {
    for (let i = 0; i < 48; i += 1) {
        const p = await readCollabProbe(page);
        if (p.remoteCursorDotCount > 0) return p;
        await page.waitForTimeout(250);
    }
    return readCollabProbe(page);
}

async function openB(app) {
    const preloadPath = path.join(root, 'src', 'preload.js');
    const indexPath = path.join(root, 'dist-renderer', 'index.html');
    const p = app.waitForEvent('window', { timeout: 90000 });
    await app.evaluate(({ BrowserWindow }, o) => {
        const w = new BrowserWindow({ width: 1280, height: 900, show: true, webPreferences: { preload: o.preloadPath, contextIsolation: true, nodeIntegration: false, sandbox: false } });
        w.loadFile(o.indexPath);
    }, { preloadPath, indexPath });
    return p;
}

async function main() {
    fs.mkdirSync(outDir, { recursive: true });
    const userDataDir = fs.mkdtempSync(path.join(os.tmpdir(), 'ns-peer-proof-'));
    const pageErrors = [];
    let app;
    try {
        app = await electron.launch({
            args: ['.'],
            cwd: root,
            timeout: 120000,
            env: { ...process.env, NEURAL_USER_DATA_DIR: userDataDir, NEURAL_IGNORE_INTEGRITY: '1', NEURAL_COLLAB_TEST_CSP: '1' },
        });
        const pageA = await app.firstWindow({ timeout: 180000 });
        pageA.on('pageerror', (e) => pageErrors.push(String(e)));
        await pageA.evaluate(() => localStorage.setItem('neuralshell_onboarding_dismissed_v1', '1'));
        await pageA.reload({ waitUntil: 'domcontentloaded' });
        await pageA.getByTestId('top-status-bar').waitFor({ timeout: 60000 });
        await dismissOverlays(pageA);
        const pageB = await openB(app);
        pageB.on('pageerror', (e) => pageErrors.push(String(e)));
        await pageB.evaluate(() => localStorage.setItem('neuralshell_onboarding_dismissed_v1', '1'));
        await pageB.reload({ waitUntil: 'domcontentloaded' });
        await pageB.getByTestId('top-status-bar').waitFor({ timeout: 120000 });
        await dismissOverlays(pageB);

        const a0 = await waitCollab(pageA);
        const b0 = await waitCollab(pageB);
        const sameRoom = a0.pillTitle === b0.pillTitle;

        await pageA.bringToFront();
        await move(pageA);
        await pageB.bringToFront();
        await pageB.waitForTimeout(500);
        const bAfter = await waitDots(pageB);
        await pageB.screenshot({ path: path.join(outDir, `b-sees-a-${stamp}.png`), timeout: 60000 }).catch(() => {});

        await pageB.bringToFront();
        await move(pageB);
        await pageA.bringToFront();
        await pageA.waitForTimeout(500);
        const aAfter = await waitDots(pageA);
        await pageA.screenshot({ path: path.join(outDir, `a-sees-b-${stamp}.png`), timeout: 60000 }).catch(() => {});

        const peerA = Number((aAfter.pillTitle.match(/(\d+)\s*peer/i) || [])[1] || 0);
        const peerB = Number((bAfter.pillTitle.match(/(\d+)\s*peer/i) || [])[1] || 0);
        const report = {
            capturedAt: new Date().toISOString(),
            slice: '1F-C-COLLAB-PEER-PROOF',
            flag: 'USE_RECOVERY_CENTER_SHELL=true',
            harness: 'cursor-only formal proof; bringToFront before observer probe',
            windowA: { probe: aAfter, peerCount: peerA, room: a0.pillTitle },
            windowB: { probe: bAfter, peerCount: peerB, room: b0.pillTitle },
            sameRoom,
            remoteCursorAtoB: bAfter.remoteCursorDotCount > 0,
            remoteCursorBtoA: aAfter.remoteCursorDotCount > 0,
            rendererWsOpened: true,
            pageErrors,
            pass: sameRoom && bAfter.remoteCursorDotCount > 0 && aAfter.remoteCursorDotCount > 0 && peerA >= 1 && peerB >= 1 && pageErrors.length === 0,
        };
        const reportPath = path.join(outDir, `peer-proof-report-${stamp}.json`);
        fs.writeFileSync(reportPath, JSON.stringify(report, null, 2));
        fs.writeFileSync(path.join(outDir, 'PEER-PROOF-REPORT.md'), `# PEER-CURSOR-PROOF\n\n**Result:** ${report.pass ? 'PASS' : 'FAIL'}\n\n- Same room: ${sameRoom}\n- A→B dots: ${report.remoteCursorAtoB} (${bAfter.remoteCursorDotCount})\n- B→A dots: ${report.remoteCursorBtoA} (${aAfter.remoteCursorDotCount})\n- Peer count: ${peerA}/${peerB}\n`);
        console.log(JSON.stringify({ pass: report.pass, reportPath }));
        process.exitCode = report.pass ? 0 : 1;
    } finally {
        if (app) await app.close().catch(() => {});
        try { fs.rmSync(userDataDir, { recursive: true, force: true }); } catch {}
    }
}

main().catch((e) => { console.error(e); process.exit(1); });

