const fs = require('fs');
const os = require('os');
const path = require('path');
const { _electron: electron } = require('playwright');

const root = path.join(__dirname, '../..');
const outDir = path.join(__dirname, 'phase-1g-rail-gate');
const stamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);

async function dismissOverlays(page) {
    for (const testId of ['firstboot-close-btn', 'onboarding-close-btn']) {
        const btn = page.getByTestId(testId);
        if (await btn.count()) await btn.first().click().catch(() => {});
    }
}

async function shot(page, name) {
    const p = path.join(outDir, `${name}-${stamp}.png`);
    await page.screenshot({ path: p, fullPage: false });
    return p;
}

async function sendChatViaInput(page, text) {
    const chatInput = page.getByTestId('chat-input').first();
    await chatInput.click({ timeout: 10000 });
    await chatInput.fill(text);
    await chatInput.press('Enter');
}

async function measureRails(page) {
    return page.evaluate(() => {
        const workbench = document.querySelector('[data-testid="workbench-rail"]')
            || document.querySelector('[data-testid="workbench-rail-panel"]');
        const panel = document.querySelector('[data-testid="workspace-panel"]');
        const main = document.querySelector('#main-workspace');
        const wr = workbench ? workbench.getBoundingClientRect() : null;
        const pr = panel ? panel.getBoundingClientRect() : null;
        const mr = main ? main.getBoundingClientRect() : null;
        const gapRight = wr && pr ? Math.round(wr.left - pr.right) : null;
        return {
            workbenchVisible: Boolean(workbench && wr && wr.width > 40),
            workbenchWidth: wr ? Math.round(wr.width) : 0,
            workspacePanelWidth: pr ? Math.round(pr.width) : 0,
            mainWidth: mr ? Math.round(mr.width) : 0,
            gapPanelToWorkbench: gapRight,
        };
    });
}

async function main() {
    fs.mkdirSync(outDir, { recursive: true });
    const userDataDir = fs.mkdtempSync(path.join(os.tmpdir(), 'neuralshell-1g-rail-gate-'));
    const pageErrors = [];
    const consoleErrors = [];
    let app;

    try {
        app = await electron.launch({
            args: ['.'],
            cwd: root,
            timeout: 120000,
            env: {
                ...process.env,
                NEURAL_USER_DATA_DIR: userDataDir,
                NEURAL_IGNORE_INTEGRITY: '1',
                NEURAL_COLLAB_TEST_CSP: '1',
            },
        });
        const page = await app.firstWindow({ timeout: 180000 });
        page.on('pageerror', (e) => pageErrors.push(String(e)));
        page.on('console', (msg) => { if (msg.type() === 'error') consoleErrors.push(msg.text()); });

        // Balanced viewport: legacy hides inline workbench; recovery should show it.
        await page.setViewportSize({ width: 1200, height: 900 });
        await page.evaluate(() => localStorage.setItem('neuralshell_onboarding_dismissed_v1', '1'));
        await page.reload({ waitUntil: 'domcontentloaded' });
        await page.getByTestId('top-status-bar').waitFor({ timeout: 60000 });
        await dismissOverlays(page);
        await page.getByTestId('workspace-panel').waitFor({ timeout: 30000 });

        const railsInitial = await measureRails(page);
        const shots = { balanced1200: await shot(page, '01-balanced-1200-initial') };

        const heroVisible = await page.getByText('Operator Hero Console').first().isVisible().catch(() => false);
        const controlDeck = await page.getByText('Control Deck').first().isVisible().catch(() => false);

        await sendChatViaInput(page, '/help');
        await page.waitForTimeout(2500);
        const helpText = await page.getByTestId('workspace-panel').innerText();
        const helpOk = helpText.includes('### NeuralShell Operator Guide') || helpText.includes('NeuralShell Operator Guide');
        shots.afterHelp = await shot(page, '02-after-help');

        await sendChatViaInput(page, 'test 1g rail gate send');
        await page.waitForTimeout(3500);
        const freeformText = await page.getByTestId('workspace-panel').innerText();
        const freeformOk = freeformText.toLowerCase().includes('test 1g rail gate send');
        shots.afterFreeform = await shot(page, '03-after-freeform');

        await page.getByTestId('layout-preset-hud-btn').click({ timeout: 5000 }).catch(() => {});
        await page.waitForTimeout(400);
        await page.getByTestId('layout-preset-balanced-btn').click({ timeout: 5000 }).catch(() => {});
        await page.waitForTimeout(400);
        shots.afterPresetClick = await shot(page, '04-after-preset-clicks');

        const railsFinal = await measureRails(page);

        const report = {
            capturedAt: new Date().toISOString(),
            slice: '1G-RAIL-GATE',
            viewport: { width: 1200, height: 900 },
            railsInitial,
            railsFinal,
            helpOk,
            freeformOk,
            pageErrors,
            consoleErrors,
            shots,
            checks: {
                clock: await page.getByTestId('clock-calendar-btn').isVisible().catch(() => false),
                layoutBar: await page.getByTestId('layout-control-bar').isVisible().catch(() => false),
                hero: heroVisible,
                controlDeck,
                chatInput: await page.getByTestId('chat-input').first().isVisible().catch(() => false),
                workbenchRail: railsFinal.workbenchVisible,
            },
        };
        fs.writeFileSync(path.join(outDir, `rail-gate-report-${stamp}.json`), JSON.stringify(report, null, 2));
        console.log(JSON.stringify(report, null, 2));
    } finally {
        if (app) await app.close().catch(() => {});
        try { fs.rmSync(userDataDir, { recursive: true, force: true }); } catch {}
    }
}

main().catch((e) => { console.error(e); process.exit(1); });

from pathlib import Path

def patch(path, pairs):
    p = Path(path)
    t = p.read_text(encoding='utf-8')
    orig = t
    for old, new in pairs:
        if old not in t:
            print('MISSING:', old[:70], 'in', p.name)
        else:
            t = t.replace(old, new, 1)
    if t != orig:
        p.write_text(t, encoding='utf-8', newline='\n')
        print('patched', p.name)
    else:
        print('no change', p.name)

