/* May 2 holo surface utilities (recovery JSX: ui-holo-panel, ui-tactile, ui-edge-glow) */
.ui-holo-panel {
    position: relative;
    overflow: hidden;
    background:
        linear-gradient(180deg, rgba(255, 255, 255, 0.045), rgba(255, 255, 255, 0.015)),
        radial-gradient(circle at top left, rgba(107, 122, 255, 0.14), transparent 32%),
        radial-gradient(circle at bottom right, rgba(16, 163, 127, 0.10), transparent 28%),
        rgba(10, 12, 20, 0.88);
    border: 1px solid rgba(255, 255, 255, 0.08);
    box-shadow: 0 14px 40px rgba(0, 0, 0, 0.34), inset 0 1px 0 rgba(255, 255, 255, 0.04);
    -webkit-backdrop-filter: blur(18px);
    backdrop-filter: blur(18px);
}

.ui-holo-panel::before {
    content: "";
    position: absolute;
    inset: 0;
    pointer-events: none;
    background: linear-gradient(118deg, transparent 0%, rgba(255, 255, 255, 0.06) 20%, rgba(255, 255, 255, 0.02) 30%, transparent 44%);
    opacity: 0;
    transform: translateX(-24%);
    transition: opacity 0.22s cubic-bezier(0.22, 1, 0.36, 1), transform 0.32s cubic-bezier(0.22, 1, 0.36, 1);
}

.ui-holo-panel:hover::before {
    opacity: 1;
    transform: translateX(8%);
}

.ui-tactile {
    transition-property: transform, box-shadow, border-color, background-color, color, opacity;
    transition-duration: 0.14s;
    transition-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
    transform-origin: center;
    will-change: transform;
}

.ui-tactile:hover {
    transform: translateY(-1px) scale(1.005);
}

.ui-tactile:active {
    transform: translateY(0) scale(0.975);
    transition-duration: 0.08s;
}

.ui-edge-glow {
    box-shadow:
        0 0 0 1px rgba(107, 122, 255, 0.10),
        0 10px 24px rgba(0, 0, 0, 0.30),
        0 0 18px rgba(66, 133, 244, 0.06);
}

.ui-edge-glow:hover {
    box-shadow:
        0 0 0 1px rgba(107, 122, 255, 0.18),
        0 14px 32px rgba(0, 0, 0, 0.34),
        0 0 24px rgba(66, 133, 244, 0.09);
}

