            if (settingsOk) {
                await page.getByTestId('settings-close-btn').click({ timeout: 5000 }).catch(() => {});
                await page.waitForTimeout(300);
            }
        } catch (err) {
            shots.settings = null;
            layoutResults.settingsError = String(err);
