main().catch((e) => { console.error(e); process.exit(1); });

const fs = require('fs');
const os = require('os');
const path = require('path');
const { _electron: electron } = require('playwright');

const root = path.join(__dirname, '../..');
const outDir = path.join(__dirname, 'phase-1g-settings-drawer');
const stamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
const mode = process.env.NS_SETTINGS_DIAG_MODE || 'recovery';

async function dismissOverlays(page) {
    for (const testId of ['firstboot-close-btn', 'onboarding-close-btn']) {
        const btn = page.getByTestId(testId);
        if (await btn.count()) await btn.first().click().catch(() => {});
    }
    await page.keyboard.press('Escape').catch(() => {});
    await page.waitForTimeout(200);
}

async function shot(page, name) {
    const p = path.join(outDir, `${mode}-${name}-${stamp}.png`);
    await page.screenshot({ path: p, fullPage: false });
    return p;
}

async function probeSettingsDom(page) {
    return page.evaluate(() => {
        const drawer = document.querySelector('[data-testid="settings-drawer"]');
        const backdrop = Array.from(document.querySelectorAll('motion.div, div')).find((el) => {
            const cls = el.className || '';
            return typeof cls === 'string' && cls.includes('fixed inset-0') && cls.includes('z-40') && cls.includes('bg-black/40');
        });
        const dialogs = Array.from(document.querySelectorAll('[role="dialog"]')).map((el) => ({
            testId: el.getAttribute('data-testid'),
            visible: el.getBoundingClientRect().width > 0,
            zIndex: window.getComputedStyle(el).zIndex,
        }));
        const settingsText = Array.from(document.querySelectorAll('h2, h1, button, [data-testid]'))
            .filter((el) => /configuration|settings/i.test(el.textContent || ''))
            .slice(0, 8)
            .map((el) => ({ tag: el.tagName, testId: el.getAttribute('data-testid'), text: (el.textContent || '').trim().slice(0, 40) }));
        const btn = document.querySelector('[data-testid="settings-open-btn"]');
        const btnRect = btn ? btn.getBoundingClientRect() : null;
        return {
            drawerPresent: Boolean(drawer),
            drawerVisible: drawer ? drawer.getBoundingClientRect().width > 40 : false,
            drawerZ: drawer ? window.getComputedStyle(drawer).zIndex : null,
            drawerDisplay: drawer ? window.getComputedStyle(drawer).display : null,
            backdropPresent: Boolean(backdrop),
            dialogs,
            settingsTextHits: settingsText,
            openBtn: btnRect ? { x: Math.round(btnRect.x), y: Math.round(btnRect.y), w: Math.round(btnRect.width), h: Math.round(btnRect.height) } : null,
            paletteOpen: Boolean(document.querySelector('[data-testid="command-palette"]')),
        };
    });
}

async function waitForDrawer(page, timeoutMs = 8000) {
    const start = Date.now();
    let last = null;
    while (Date.now() - start < timeoutMs) {
        last = await probeSettingsDom(page);
        if (last.drawerVisible) return { ok: true, waitedMs: Date.now() - start, probe: last };
        await page.waitForTimeout(250);
    }
    return { ok: false, waitedMs: Date.now() - start, probe: last };
}

async function runMode() {
    fs.mkdirSync(outDir, { recursive: true });
    const userDataDir = fs.mkdtempSync(path.join(os.tmpdir(), `neuralshell-settings-diag-${mode}-`));
    const pageErrors = [];
    const consoleErrors = [];
    const shots = {};
    let app;

    try {
        app = await electron.launch({
            args: ['.'],
            cwd: root,
            timeout: 120000,
            env: {
                ...process.env,
                NEURAL_USER_DATA_DIR: userDataDir,
                NEURAL_IGNORE_INTEGRITY: '1',
                NEURAL_COLLAB_TEST_CSP: '1',
            },
        });
        const page = await app.firstWindow({ timeout: 180000 });
        page.on('pageerror', (e) => pageErrors.push(String(e)));
        page.on('console', (msg) => { if (msg.type() === 'error') consoleErrors.push(msg.text()); });

        await page.setViewportSize({ width: 1200, height: 900 });
        await page.evaluate(() => localStorage.setItem('neuralshell_onboarding_dismissed_v1', '1'));
        await page.reload({ waitUntil: 'domcontentloaded' });
        await page.getByTestId('top-status-bar').waitFor({ timeout: 60000 });
        await dismissOverlays(page);
        await page.getByTestId('settings-open-btn').waitFor({ timeout: 15000 });

        shots.before = await shot(page, '01-before-settings');

        const probeBefore = await probeSettingsDom(page);

        // Method 1: click settings-open-btn
        await page.getByTestId('settings-open-btn').click({ timeout: 8000 });
        shots.afterClick500ms = await shot(page, '02-after-click-500ms');
        await page.waitForTimeout(500);
        const probe500 = await probeSettingsDom(page);

        const waitClick = await waitForDrawer(page, 8000);
        shots.afterClickWait = await shot(page, '03-after-click-wait');

        let closeOk = false;
        if (waitClick.ok) {
            closeOk = await page.getByTestId('settings-close-btn').click({ timeout: 5000 }).then(() => true).catch(() => false);
            await page.waitForTimeout(300);
        }

        await dismissOverlays(page);

        // Method 2: Ctrl+,
        await page.keyboard.press('Control+,');
        shots.afterCtrlComma500ms = await shot(page, '04-after-ctrl-comma-500ms');
        await page.waitForTimeout(500);
        const waitShortcut = await waitForDrawer(page, 8000);
        shots.afterCtrlCommaWait = await shot(page, '05-after-ctrl-comma-wait');

        // Method 3: force click via evaluate
        await dismissOverlays(page);
        await page.evaluate(() => {
            const btn = document.querySelector('[data-testid="settings-open-btn"]');
            if (btn) btn.click();
        });
        const waitEval = await waitForDrawer(page, 8000);
        shots.afterEvalWait = await shot(page, '06-after-eval-click-wait');

        const report = {
            capturedAt: new Date().toISOString(),
            slice: '1G-SETTINGS-DRAWER-DIAG',
            mode,
            flag: mode === 'recovery' ? 'USE_RECOVERY_CENTER_SHELL=true' : 'USE_RECOVERY_CENTER_SHELL=false',
            probeBefore,
            click500ms: probe500,
            clickWait: waitClick,
            shortcutWait: waitShortcut,
            evalWait: waitEval,
            closeOk,
            pageErrors,
            consoleErrors,
            shots,
            settingsDrawerDetected: waitClick.ok || waitShortcut.ok || waitEval.ok,
        };

        const reportPath = path.join(outDir, `settings-drawer-diag-${mode}-${stamp}.json`);
        fs.writeFileSync(reportPath, JSON.stringify(report, null, 2));
        console.log(JSON.stringify({ ...report, reportPath }, null, 2));
    } finally {
        if (app) await app.close().catch(() => {});
        try { fs.rmSync(userDataDir, { recursive: true, force: true }); } catch {}
    }
}

runMode().catch((e) => { console.error(e); process.exit(1); });

