const fs = require('fs');
const os = require('os');
const path = require('path');
const { _electron: electron } = require('playwright');

const root = path.join(__dirname, '../..');
const outDir = path.join(__dirname, 'phase-default-flip-gate');
const stamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);

async function dismissOverlays(page) {
    for (const testId of ['firstboot-close-btn', 'onboarding-close-btn']) {
        const btn = page.getByTestId(testId);
        if (await btn.count()) await btn.first().click().catch(() => {});
    }
    await page.evaluate(() => {
        localStorage.setItem('neuralshell_first_boot_completed_v1', '1');
        localStorage.setItem('neuralshell_onboarding_dismissed_v1', '1');
    });
}

async function shot(page, name) {
    const p = path.join(outDir, `${name}-${stamp}.png`);
    await page.screenshot({ path: p, fullPage: false });
    return p;
}

async function sendChatViaInput(page, text) {
    const chatInput = page.getByTestId('chat-input').first();
    await chatInput.click({ timeout: 10000 });
    await chatInput.fill(text);
    await chatInput.press('Enter');
}

function isBenignConsoleError(text) {
    const t = String(text || '');
    return t.includes('ERR_BLOCKED_BY_CLIENT') || t.includes('Content Security Policy') || t.includes('Refused to connect');
}

async function main() {
    fs.mkdirSync(outDir, { recursive: true });
    const userDataDir = fs.mkdtempSync(path.join(os.tmpdir(), 'neuralshell-default-flip-gate-'));
    const pageErrors = [];
    const consoleErrors = [];
    let app;

    try {
        app = await electron.launch({
            args: ['.'],
            cwd: root,
            timeout: 120000,
            env: { ...process.env, NEURAL_USER_DATA_DIR: userDataDir, NEURAL_IGNORE_INTEGRITY: '1', NEURAL_COLLAB_TEST_CSP: '1' },
        });
        const page = await app.firstWindow({ timeout: 180000 });
        page.on('pageerror', (e) => pageErrors.push(String(e)));
        page.on('console', (msg) => { if (msg.type() === 'error' && !isBenignConsoleError(msg.text())) consoleErrors.push(msg.text()); });

        await page.setViewportSize({ width: 1200, height: 900 });
        await dismissOverlays(page);
        await page.reload({ waitUntil: 'domcontentloaded' });
        await page.getByTestId('top-status-bar').waitFor({ timeout: 60000 });
        await dismissOverlays(page);
        await page.getByTestId('workspace-panel').waitFor({ timeout: 30000 });

        const shots = { initial: await shot(page, '01-initial-empty-state') };
        const checks = {
            clock: await page.getByTestId('clock-calendar-btn').isVisible().catch(() => false),
            layoutBar: await page.getByTestId('layout-control-bar').isVisible().catch(() => false),
            hero: await page.getByText('Operator Hero Console').first().isVisible().catch(() => false),
            controlDeck: await page.getByText('Control Deck').first().isVisible().catch(() => false),
            holoPanels: (await page.locator('.ui-holo-panel').count()) > 0,
            workbenchRail: await page.getByTestId('workbench-rail').isVisible().catch(() => false),
        };
        for (const id of ['hud', 'compact', 'balanced', 'wide']) {
            checks[`preset_${id}`] = await page.getByTestId(`layout-preset-${id}-btn`).isVisible().catch(() => false);
        }

        await sendChatViaInput(page, '/help');
        await page.waitForTimeout(2500);
        const helpOk = (await page.getByTestId('workspace-panel').innerText()).includes('Operator Guide');
        shots.afterHelp = await shot(page, '02-after-help');

        await sendChatViaInput(page, 'default flip gate freeform');
        await page.waitForTimeout(3500);
        const freeformOk = (await page.getByTestId('workspace-panel').innerText()).toLowerCase().includes('default flip gate freeform');
        shots.afterFreeform = await shot(page, '03-after-freeform');

        await page.getByTestId('command-palette-btn').click({ timeout: 8000 });
        await page.waitForTimeout(500);
        const commandPaletteOk = await page.getByTestId('command-palette').isVisible().catch(() => false);
        shots.commandPalette = await shot(page, '04-command-palette');
        await page.keyboard.press('Escape');

        await page.getByTestId('settings-open-btn').click({ timeout: 8000 });
        await page.waitForTimeout(500);
        const settingsOk = await page.getByTestId('settings-drawer').isVisible().catch(() => false);
        shots.settings = await shot(page, '05-settings-drawer');
        if (settingsOk) await page.getByTestId('settings-close-btn').click({ timeout: 5000 }).catch(() => {});

        for (const id of ['hud', 'compact', 'balanced', 'wide']) {
            await page.getByTestId(`layout-preset-${id}-btn`).click({ timeout: 5000 }).catch(() => {});
            await page.waitForTimeout(300);
        }
        shots.afterLayoutPresets = await shot(page, '06-after-layout-presets');

        const pass = helpOk && freeformOk && commandPaletteOk && settingsOk && pageErrors.length === 0
            && checks.clock && checks.hero && checks.controlDeck && checks.holoPanels && checks.workbenchRail;

        const report = {
            capturedAt: new Date().toISOString(),
            slice: 'DEFAULT-FLIP-GATE',
            flag: 'USE_RECOVERY_CENTER_SHELL=true (default)',
            checks,
            helpOk,
            freeformOk,
            commandPaletteOk,
            settingsOk,
            pageErrors,
            consoleErrors,
            shots,
            pass,
        };
        const reportPath = path.join(outDir, `default-flip-gate-report-${stamp}.json`);
        fs.writeFileSync(reportPath, JSON.stringify(report, null, 2));
        console.log(JSON.stringify({ ...report, reportPath }, null, 2));
        if (!pass) process.exit(1);
    } finally {
        if (app) await app.close().catch(() => {});
        try { fs.rmSync(userDataDir, { recursive: true, force: true }); } catch {}
    }
}

main().catch((e) => { console.error(e); process.exit(1); });

